<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class OfficeArchiveController extends Controller{
private function archive(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('document_clerk')||$r->user()->canDo('office.archive'),403);}
public function cases(Request $r){$this->archive($r);$rows=DB::table('office_case_files')->orderByDesc('year')->orderBy('index_code')->get();return view('office.cases',compact('rows'));}
public function caseStore(Request $r){$this->archive($r);$d=$r->validate(['index_code'=>'required|string|max:100|unique:office_case_files,index_code','title'=>'required|string|max:500','year'=>'required|integer|min:2000|max:2200','retention_period'=>'nullable|string|max:100','opened_on'=>'required|date','note'=>'nullable|string|max:3000']);DB::table('office_case_files')->insert($d+['status'=>'open','created_at'=>now(),'updated_at'=>now()]);return back();}
public function put(Request $r,$case,$document){$this->archive($r);abort_unless(DB::table('office_case_files')->where(['id'=>$case,'status'=>'open'])->exists(),409);DB::table('office_case_documents')->insertOrIgnore(['office_case_file_id'=>$case,'official_document_id'=>$document,'created_at'=>now(),'updated_at'=>now()]);DB::table('official_documents')->where('id',$document)->whereIn('status',['signed','closed'])->update(['status'=>'archived','closed_at'=>now(),'closed_by'=>$r->user()->id,'updated_at'=>now()]);return back();}
public function close(Request $r,$case){$this->archive($r);DB::table('office_case_files')->where('id',$case)->update(['status'=>'closed','closed_on'=>date('Y-m-d'),'updated_at'=>now()]);return back();}
public function dispatch(Request $r,$document){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('document_clerk')||$r->user()->canDo('office.dispatch'),403);$d=$r->validate(['method'=>'required|in:email,post,courier,hand,system','recipient'=>'required|string|max:500','address'=>'nullable|string|max:1000','tracking_number'=>'nullable|string|max:255','status'=>'required|in:prepared,sent,delivered,returned']);$d['sent_at']=in_array($d['status'],['sent','delivered'])?now():null;DB::table('office_dispatches')->insert($d+['official_document_id'=>$document,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);DB::table('official_document_events')->insert(['official_document_id'=>$document,'user_id'=>$r->user()->id,'event'=>'dispatch_'.$d['status'],'details'=>$d['method'].' → '.$d['recipient'],'created_at'=>now(),'updated_at'=>now()]);return back();}
}